const $=id=>document.getElementById(id),KEY='braise-v1';
const fresh=()=>({gold:0,xp:0,level:1,stage:1,kills:0,weapon:0,armor:0,luck:0,last:Date.now()});
let s;try{s={...fresh(),...JSON.parse(localStorage.getItem(KEY)||'null')};if(!Number.isFinite(s.stage)||s.stage<1)throw Error();}catch{s=fresh()}
let paused=false,boss=false,cool=0,hp=100,enemyHP=0,enemyMax=0,saveOk=true;
const attack=()=>8+s.weapon*4+(s.level-1)*2,maxHP=()=>100+s.armor*35+(s.level-1)*10,reward=()=>8+s.stage*3+s.luck*3,cost=k=>Math.floor(({weapon:24,armor:30,luck:40}[k])*1.6**s[k]);
const names=['Maraudeur des cryptes','Sentinelle déchue','Spectre des cendres'];
function log(t){$('message').textContent=t}function save(){s.last=Date.now();try{localStorage.setItem(KEY,JSON.stringify(s))}catch{saveOk=false;$('saved').textContent='Sauvegarde indisponible'}}
function gainXP(n){s.xp+=n;while(s.xp>=s.level*35){s.xp-=s.level*35;s.level++;hp=maxHP();log(`Niveau ${s.level} ! La braise grandit. Vitalité restaurée.`)}}
function spawn(){enemyMax=Math.floor((32+s.stage*14)*(boss?5:1));enemyHP=enemyMax}
function render(){for(const [id,val] of Object.entries({gold:Math.floor(s.gold).toLocaleString('fr-FR'),stage:String(s.stage).padStart(2,'0'),floor:`Étage ${s.stage}${boss?' · Gardien':''}`,level:s.level,attack:attack(),health:`${Math.max(0,Math.ceil(hp))} / ${maxHP()}`,reward:reward(),xptext:`${s.xp} / ${s.level*35}`,progress:`${s.kills} / 5 ennemis vaincus`,enemy:boss?'Le Gardien de braise':names[(s.stage-1)%3],enemyhp:`${Math.max(0,Math.ceil(enemyHP))} / ${enemyMax}`}))$(id).textContent=val;$('xpbar').style.width=`${s.xp/(s.level*35)*100}%`;$('enemybar').style.width=`${enemyHP/enemyMax*100}%`;$('dots').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i<s.kills?'done':''}"></i>`).join('');$('boss').disabled=s.kills<5||boss;$('boss').innerHTML=boss?'⚔ Gardien en cours…':`⚔ Affronter le gardien<small>${s.kills>=5?'Prêt · ouvre le prochain étage':'5 victoires requises'}</small>`;$('power').disabled=cool>0||paused;$('cooldown').textContent=cool>0?`Recharge · ${cool} s`:'Dégâts × 4 · prêt';for(const k of ['weapon','armor','luck']){const b=$('buy-'+k);b.disabled=s.gold<cost(k);b.textContent=`◈ ${cost(k)}`;$('desc-'+k).textContent=`Niv. ${s[k]} · ${k==='weapon'?'+4 attaque':k==='armor'?'+35 vitalité':'+3 or / victoire'}`}}
for(const [k,title,img] of [['weapon','Affûter la lame',104],['armor','Renforcer l’armure',100],['luck','Charme de fortune',110]]){const row=document.createElement('div');row.className='upgrade';row.innerHTML=`<img src="assets/Tiles/tile_${String(img).padStart(4,'0')}.png" alt=""><div><b>${title}</b><p id="desc-${k}"></p></div><button id="buy-${k}" aria-label="${title}"></button>`;$('upgrades').append(row);$('buy-'+k).onclick=()=>{if(s.gold<cost(k))return;s.gold-=cost(k);s[k]++;if(k==='armor')hp+=35;log(`${title} : niveau ${s[k]}.`);save();render()}}
function strike(mult=1){if(paused)return;const damage=attack()*mult;enemyHP-=damage;$('float').textContent=`−${damage}`;$('float').classList.remove('hit');void $('float').offsetWidth;$('float').classList.add('hit');if(enemyHP<=0){const wonBoss=boss;s.gold+=reward()*(wonBoss?8:1);gainXP(wonBoss?40:10);if(wonBoss){s.stage++;s.kills=0;boss=false;hp=maxHP();log(`Gardien vaincu ! L’étage ${s.stage} s’ouvre. Vitalité restaurée.`)}else{s.kills=Math.min(5,s.kills+1);log(`Ennemi vaincu · +${reward()} or · +10 expérience`);hp=Math.min(maxHP(),hp+8)}spawn()}else{hp-=Math.max(1,Math.floor((boss?10:3)+s.stage*1.4-s.armor*1.5));if(hp<=0){boss=false;hp=maxHP();spawn();log('Repli au camp. Vitalité restaurée, ton butin est conservé.')}}render()}
$('boss').onclick=()=>{if(s.kills<5||boss)return;boss=true;hp=maxHP();spawn();log('Le gardien approche. Fais parler la braise !');render()};$('power').onclick=()=>{if(cool||paused)return;cool=15;strike(4)};$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶ Reprendre':'Ⅱ Pause';render()};$('reset').onclick=()=>{if(!confirm('Recommencer ? Toute la progression locale sera effacée.'))return;s=fresh();boss=false;cool=0;hp=maxHP();spawn();save();render();log('Une nouvelle braise s’éveille.')};$('claim').onclick=()=>$('welcome').close();
const away=Math.max(0,Math.min(28800,(Date.now()-s.last)/1000));if(away>60){const wins=Math.floor(away/(Math.ceil((32+s.stage*14)/attack())*1.2));const gold=wins*reward();s.gold+=gold;gainXP(wins*10);$('offline').textContent=`Pendant ton absence : ${wins} ennemis vaincus et ${gold.toLocaleString('fr-FR')} pièces d’or récoltées (8 h maximum).`;$('welcome').showModal()}
hp=maxHP();spawn();render();setInterval(()=>strike(),1200);setInterval(()=>{if(cool>0&&!paused)cool--;render()},1000);setInterval(save,5000);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});window.addEventListener('pagehide',save);
const canvas=$('world'),ctx=canvas.getContext('2d'),tiles=new Map();ctx.imageSmoothingEnabled=false;for(const n of [0,1,12,13,24,25,36,37,38,39,89,48,49,50,51,52,53,60,72,73,84,96,108,109,110,120,121,122]){const img=new Image();img.src=`assets/Tiles/tile_${String(n).padStart(4,'0')}.png`;tiles.set(n,img)}
function tile(n,x,y,size=48){const im=tiles.get(n);if(im?.complete&&im.naturalWidth)ctx.drawImage(im,x,y,size,size)}
function draw(t){ctx.fillStyle='#29352e';ctx.fillRect(0,0,768,384);for(let y=0;y<8;y++)for(let x=0;x<16;x++){ctx.fillStyle=(x+y)%3===0?'#303c32':'#2c382f';ctx.fillRect(x*48,y*48,47,47);ctx.fillStyle='#374237';if((x*7+y*3)%5===0)ctx.fillRect(x*48+9,y*48+13,12,3)}for(let x=0;x<16;x++){tile(38,x*48,0);tile(39,x*48,48)}for(let y=2;y<8;y++){tile(12,0,y*48);tile(12,720,y*48)}tile(1,80,96);tile(1,640,96);tile(89,100,272);tile(73,624,280);tile(72,580,104);for(const x of [180,555]){const glow=ctx.createRadialGradient(x,108,0,x,108,95);glow.addColorStop(0,'#e9a45b44');glow.addColorStop(1,'#e9a45b00');ctx.fillStyle=glow;ctx.fillRect(x-95,13,190,190);ctx.fillStyle='#5a4932';ctx.fillRect(x-3,97,6,24);ctx.fillStyle='#f2b967';ctx.fillRect(x-5,86+Math.sin(t/150)*2,10,13);ctx.fillStyle='#ffe3a0';ctx.fillRect(x-2,89,4,7)}const bob=matchMedia('(prefers-reduced-motion: reduce)').matches?0:Math.sin(t/220)*3;ctx.fillStyle='#0c171a66';for(const x of [277,480]){ctx.beginPath();ctx.ellipse(x+32,260,32,10,0,0,Math.PI*2);ctx.fill()}tile(96,270+(paused?0:Math.sin(t/190)*3),187+bob,72);tile(boss?110:[108,121,109][(s.stage-1)%3],465,185-bob,boss?88:72);ctx.fillStyle='#b8ce9b';ctx.fillRect(276,171,58*(hp/maxHP()),3);requestAnimationFrame(draw)}requestAnimationFrame(draw);
